<script lang="ts">
  import { onMount } from 'svelte'; let users: any[] = []; let email = ''; let name = ''; let message = '';
  async function load() { users = (await (await fetch('/api/admin/users')).json()).users ?? []; }
  async function invite() { const response = await fetch('/api/admin/users', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ email, name }) }); const result = await response.json(); if (!response.ok) { message = result.error; return; } message = 'User created'; email = ''; name = ''; await load(); }
  onMount(load);
</script>
<main><a href="/admin">← Admin</a><h1>Users</h1><p>Users have memberships and roles per site.</p><form onsubmit={(event) => { event.preventDefault(); invite(); }}><input bind:value={name} placeholder="Full name" required /><input bind:value={email} type="email" placeholder="Email" required /><button>Create invite</button></form>{#if message}<p>{message}</p>{/if}<table><thead><tr><th>Name</th><th>Email</th><th>Memberships</th><th>Status</th></tr></thead><tbody>{#each users as user}<tr><td>{user.name}</td><td>{user.email}</td><td>{user.memberships.map((membership: any) => membership.role).join(', ')}</td><td>{user.disabled ? 'disabled' : 'active'}</td></tr>{/each}</tbody></table></main><style>main{max-width:900px;margin:3rem auto;font:16px system-ui}a{color:#1261a0}form{display:flex;gap:.5rem;margin:1.5rem 0}input,button{padding:.65rem;border:1px solid #ccd3da;border-radius:6px}button{background:#1261a0;color:white}table{width:100%;border-collapse:collapse}td,th{text-align:left;border-bottom:1px solid #e5e7eb;padding:.75rem}</style>
